}

using {{ SolutionName }}.Application.Abstractions.Logging;

namespace {{ SolutionName }}.Infrastructure.Logging;

public sealed class LogHelper : ILogHelper
{
    public void Info(string message)
    {
        Console.WriteLine($"[INFO] {message}");
    }

    public void Error(string message, Exception? exception = null)
    {
        Console.WriteLine($"[ERROR] {message}");
        if (exception is not null)
        {
            Console.WriteLine(exception);
        }
    }
}

using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.OpenApi.Models;

namespace {{ SolutionName }}.Api.Extensions;

public static class SwaggerServiceExtensions
{
    public static IServiceCollection AddProjectSwagger(this IServiceCollection services, string title)
    {
        services.AddEndpointsApiExplorer();
        services.AddSwaggerGen(options =>
        {
            options.SwaggerDoc("v1", new OpenApiInfo
            {
                Title = title,
                Version = "v1"
            });
        });

        return services;
    }

    public static WebApplication UseProjectSwagger(this WebApplication app)
    {
        app.UseSwagger();
        app.UseSwaggerUI();
        return app;
    }
}

